DROP POLICY IF EXISTS "plans readable" ON public.plans;
CREATE POLICY "plans readable" ON public.plans FOR SELECT TO anon, authenticated USING (status = 'live' OR public.is_control(auth.uid()));
DROP POLICY IF EXISTS "plan reports readable" ON public.plan_reports;
CREATE POLICY "plan reports readable" ON public.plan_reports FOR SELECT TO anon, authenticated USING (EXISTS (SELECT 1 FROM public.plans p WHERE p.id = plan_reports.plan_id AND (p.status = 'live' OR public.is_control(auth.uid()))));
DROP POLICY IF EXISTS "report_prices_read" ON public.report_prices;
CREATE POLICY "report_prices_read" ON public.report_prices FOR SELECT TO authenticated USING (auth.uid() IS NOT NULL);
DROP POLICY IF EXISTS "prd2_roles_select_authenticated" ON public.roles;
CREATE POLICY "prd2_roles_select_authenticated" ON public.roles FOR SELECT TO authenticated USING (auth.uid() IS NOT NULL);
DROP POLICY IF EXISTS "listed_companies readable by authenticated" ON public.listed_companies;
CREATE POLICY "listed_companies readable by authenticated" ON public.listed_companies FOR SELECT TO authenticated USING (auth.uid() IS NOT NULL);
DROP POLICY IF EXISTS "peers readable by authenticated" ON public.peers;
CREATE POLICY "peers readable by authenticated" ON public.peers FOR SELECT TO authenticated USING (auth.uid() IS NOT NULL);
DROP POLICY IF EXISTS "peer_sets readable by authenticated" ON public.peer_sets;
CREATE POLICY "peer_sets readable by authenticated" ON public.peer_sets FOR SELECT TO authenticated USING (auth.uid() IS NOT NULL);
DROP POLICY IF EXISTS "peer_set_members readable by authenticated" ON public.peer_set_members;
CREATE POLICY "peer_set_members readable by authenticated" ON public.peer_set_members FOR SELECT TO authenticated USING (auth.uid() IS NOT NULL);
DROP POLICY IF EXISTS "Signed-in users read investor images" ON public.investor_images;
CREATE POLICY "Signed-in users read investor images" ON public.investor_images FOR SELECT TO authenticated USING (auth.uid() IS NOT NULL);
DROP POLICY IF EXISTS "Anyone reads sector images" ON public.sector_images;
CREATE POLICY "Signed-in users read sector images" ON public.sector_images FOR SELECT TO authenticated USING (auth.uid() IS NOT NULL);
DROP POLICY IF EXISTS "Public images are readable" ON storage.objects;
CREATE POLICY "Signed-in users read public images" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'public-images' AND auth.uid() IS NOT NULL);